const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const cmds=[
  ["evaldata", "rg -n --glob '*.lean' \"PicRankOneEvaluationDivisorData|EvaluationDivisorData|evaluationDivisorData|evaluationDivisor|canonical.*evaluation|evaluation.*canonical\" . ../Algebraic-Jacobian-Challenge"],
  ["abelrep", "rg -n --glob '*.lean' \"rankOneAbelIso|AbelIso|pic0RepresentableBy|RepresentableBy|representableBy\" . ../Algebraic-Jacobian-Challenge"],
  ["jacdefs", "rg -n --glob '*.lean' \"(noncomputable )?(def|abbrev|theorem|lemma).*jacobianData|jacobianData|toJacobianData|JacobianData\\.of|ofRepresentableBy|ofCharts\" . ../Algebraic-Jacobian-Challenge"],
  ["aliases", "rg -n --glob '*.lean' \"rankOne|pic0|Pic0|PicRep|Jacobian|Picard\" AlgebraicJacobian ../Algebraic-Jacobian-Challenge/AlgebraicJacobian | rg -i \"old|legacy|route|producer|assemble|construct|build|exists|canonical|global|atlas|chart|datum\""]
];
const rs=await Promise.all(cmds.map(async ([name,cmd])=>{
  const r=await tools.exec_command({cmd,workdir:wd,yield_time_ms:10000,max_output_tokens:50000});
  return `===== ${name} =====\n${r.output}`;
}));
rs.forEach(text);

