const wd="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const specs=[
 ["divrank","rg -n --glob '*.lean' 'DivRankOneOpenData|divRankOneOpenData|divRankOnePresentationPreimageRepresenter|divRankOne.*Represent|rankOneDivisorLocus|rankOneLocus' AlgebraicJacobian/Picard"],
 ["iso","rg -n --glob '*.lean' 'Functor\\.RepresentableBy\\.(ofIso|ofNatIso|ofIso|equiv|iso)|RepresentableBy\\.ofIso|representableBy.*ofIso|ofIso.*RepresentableBy|representableByIso|iso.*representable' AlgebraicJacobian ../Algebraic-Jacobian-Challenge/AlgebraicJacobian"],
 ["pic0trans","rg -n --glob '*.lean' 'pic0.*(iso|equiv|transport|represent|restrict|open)|RepresentableBy.*pic0|pic0.*RepresentableBy|pic0Sigma.*(iso|equiv)|pic0TypeFunctor.*(iso|equiv|map)' AlgebraicJacobian/Picard"],
 ["jacprod","rg -n --glob '*.lean' '^(noncomputable )?(def|abbrev|theorem|lemma) .*jacobian|^(noncomputable )?(def|abbrev|theorem|lemma) .*Jacobian|JacobianData \\w+ :=|: JacobianData' AlgebraicJacobian/Picard AlgebraicJacobian/Challenge.lean"]
];
const rs=await Promise.all(specs.map(async ([n,c])=>{const r=await tools.exec_command({cmd:c,workdir:wd,yield_time_ms:10000,max_output_tokens:30000});return `===== ${n} =====\n${r.output}`;}));rs.forEach(text);
